    /* [TEST] 각 지점별 거리구하기  */
    onlyGPSDistanceTestFunction: function(gps, lat, lon, location) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        Number.prototype.toRad = function() {
            return this * Math.PI / 100;
        };

        // 35.145397, 129.065777, '부산은행(문현본점)');
        lat = 35.145397;
        lon = 129.065777;
        location = '부산은행(문현본점)';

        lat = Number(lat);
        lon = Number(lon);

        var lat1 = gps.latitude;
        var lon1 = gps.longitude;

        if(!lat1 || !lon1){
            return 'GPS 수신불가';
        }

        var lat2 = lat;
        var lon2 = lon;

        var R = 6371; // 지구 반지름 = 6371 km

        var x1 = lat2 - lat1;
        var dLat = x1.toRad();

        var x2 = lon2 - lon1;
        var dLon = x2.toRad();

        var a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
                Math.cos(lat1.toRad()) * Math.cos(lat2.toRad()) *
                Math.sin(dLon / 2) * Math.sin(dLon / 2);
        var c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
        var d = R * c;

        var km = String(Math.floor(d)); // '18'
        var strKm = d.toFixed(3); // '18.852'

        var m_tmp = (Number(strKm) - Number(km)) * 1000;
        var m = Number(Math.floor(m_tmp));

        var result = '';
        if(km == '0'){
            result = location + ' 근무지와의 거리 : ' + m +'m';
        } else {
            result = location + ' 근무지와의 거리 : ' + km + 'km' + ' ' + m +'m';
        }

        return result;

    },

