    getServerTime: function(runner) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            values = {};


        // Service 호출
        Ext.Ajax.request({
            headers : {
                viewId : me.getViewId(), // userAlias
                serviceId : 'HwmDaySvc.findAllHwmDayAply'
            },
            jsonData : values,
            scope : me,
            success : function(response) {
                var result = Ext.JSON.decode(response.responseText); // 서버응답결과 JSON 변환

                // Service 성공 했을 경우 기능
                vm.set('runner', null);
                vm.set('task', null);
                runner.stopAll();

                // 실시간 시각 구하기 - 서버 기준
                this.getServerDate(result.timestamp);
            }
        });
    },

