    /* 출근 버튼 Event */
    onInTap: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        switch (vm.get('actionNeed')) {
            //출/퇴근 버튼 - 출근
            case vm.get('actionAttendence'):
            me.checkWkplc(me, false);
            break;
            //출/퇴근 버튼 - 출/퇴근 둘 다 불가
            default:
            Ext.Msg.alert('확인', '오늘은 이미 출퇴근 처리가 되었습니다.<br / >');
            break;
        }

    },

    /* 퇴근 버튼 Event */
    onOutTap: function(button, e, eOpts) {
        this.checkWkplc(this, true);
    },

    /* 출퇴근 체크 초기화 */
    initialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        // 세션 정보

        var empeNmPsit = SecurityUtils.getPrincipal().empeNm + ' ' + SecurityUtils.getPrincipal().empePsitNm;
        if(Constants.managerEmpeRsbCds.indexOf(SecurityUtils.getPrincipal().empeRsbCd) > -1){
            empeNmPsit = SecurityUtils.getPrincipal().empeNm + ' ' + SecurityUtils.getPrincipal().empeRsbNm;
        }

        var dpnm = SecurityUtils.getPrincipal().dpnm;
        refs.empeNm.setHtml(empeNmPsit);
        refs.dpnm.setHtml(dpnm);

        // 출.퇴근 버튼 hidden : onSelect()에서 출근, 퇴근 상태를 구분하므로, 그 이전까지는 출퇴근버튼 모두 hidden // onSelect에서 hidden false
        refs.btnInOut.setHidden(true);
        refs.startSpace.setHidden(false); // 출퇴근버튼영역(btnInOut)이 hidden 이면 이름, 부서명, GPS 아이콘이 아래로 당겨졌다가 출퇴근버튼영역이 hidden false 되면 다시 올라가게 되는 현상을 막기위한 공간, 출퇴근버튼영역이 hidden false 될 때 hidden 시킴

        // 사진, 위치 정보 조회
        this.onSelect();
    },

